		// le CI qui lance `biome check .` (lint + format + organize imports).
		exec(`npx --no-install biome check --write --error-on-warnings "${filePath}"`);
		return null;
	} catch (err) {
		const output = err.stdout?.toString() ?? "";
		return output ? { message: `Biome: ${output.trim()}\n` } : null;
	}
}

/* v8 ignore next 5 */
