	it("lance les checks si un tsconfig/package.json a changé sans fichier .ts", () => {
		const opts = makeOpts();
		opts.changed = ["tsconfig.json"];
		run(opts);
		expect(opts.exec).toHaveBeenCalledWith(expect.stringContaining("tsc"));
