"""Reads Claude notifications out loud via system TTS (Notification)."""
import json
import re
import subprocess
import sys


def _default_exec(cmd):
    subprocess.run(
        cmd, shell=True, timeout=15, check=True, stdout=subprocess.DEVNULL, stderr=subprocess.DEVNULL
