_spec.loader.exec_module(hook)


def _ok(cmd, **kwargs):
    return None


def _fail(stdout):
    def fail(cmd, **kwargs):
        raise subprocess.CalledProcessError(1, cmd, output=stdout)

    return fail


def test_ignores_non_py_files():
