    assert hook.run(_input("https://example.com"), **_run_kwargs(deps)) is None


def test_includes_domain_in_reason():
    result = hook.run(_input("https://nextjs.org/docs"), **_run_kwargs(_deps()))
    assert "nextjs.org" in result["reason"]

