	});

	it("no-op quand aucun fichier source modifié (seulement doc/config/lock)", () => {
		const exec = makeExec("README.md\npackage.json\npnpm-lock.yaml\n");
		expect(run({}, { exec, projectDir: "/p" })).toBeNull();
	});

