			{ tool_input: { file_path: "a.java" } },
			{ exec: makeExecFail("error: expected ';'") },
		);
		expect(result?.message).toContain("[java-format]");
		expect(result?.message).toContain("expected ';'");
	});

	it("retourne null si l'outil est absent (échec sans output)", () => {
