#!/usr/bin/env node
// @hookstack post-edit-java-compile
// Vérifie la compilation Java après édition (PostToolUse Write|Edit)
import { execSync } from "node:child_process";
import { readFileSync } from "node:fs";
import { fileURLToPath } from "node:url";
import { detectBuildTool } from "./lib/java-build.mjs";

function makeDefaultExec(projectDir) {
	return (cmd) =>
		execSync(cmd, { cwd: projectDir, stdio: "pipe", timeout: 60_000 });
}

export function run(
	input,
	{ exec, exists, projectDir = process.env.CLAUDE_PROJECT_DIR, platform } = {},
) {
	const filePath = input.tool_input?.file_path ?? input.tool_input?.path ?? "";
	if (!filePath.endsWith(".java")) return null;

	const cwd = projectDir ?? process.cwd();
	const build = detectBuildTool({ exists, projectDir: cwd, platform });
	if (!build) return null; // pas d'outil de build Java reconnu

	const doExec = exec ?? makeDefaultExec(cwd);
	const task = build.tool === "maven" ? "compile" : "compileJava";
	try {
		doExec(`${build.cmd} -q ${task}`);
		return null;
	} catch (err) {
		const output = err.stdout?.toString() ?? "";
		return output ? { message: `[java-compile] ${output.trim()}\n` } : null;
	}
}

/* v8 ignore next 5 */
if (process.argv[1] === fileURLToPath(import.meta.url)) {
	const input = JSON.parse(readFileSync(0, "utf8"));
	const result = run(input);
	if (result?.message) process.stderr.write(result.message);
}

companion_files.snippet:
// @hookstack lib-java-build
// Helper partagé par les hooks Java (post-edit-java-compile, stop-java-test).
// Détecte l'outil de build du projet : wrapper Gradle (./gradlew) d'abord, puis
// Gradle (build.gradle), puis Maven (pom.xml). Retourne { tool, cmd } ou null
// si le projet n'a pas d'outil de build Java reconnu.
import { existsSync } from "node:fs";
import { join } from "node:path";

export function detectBuildTool({
	exists = existsSync,
	projectDir = process.env.CLAUDE_PROJECT_DIR ?? process.cwd(),
	platform = process.platform,
} = {}) {
	const has = (f) => exists(join(projectDir, f));

	// Le wrapper Gradle épingle la version du toolchain — toujours préféré.
	if (has("gradlew") || has("gradlew.bat"))
		return { tool: "gradle", cmd: platform === "win32" ? "gradlew.bat" : "./gradlew" };
	if (has("build.gradle") || has("build.gradle.kts"))
		return { tool: "gradle", cmd: "gradle" };
	if (has("pom.xml")) return { tool: "maven", cmd: "mvn" };
	return null;
}

